PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?name WHERE {
  ?trial a oncologia:Trial ;
         oncologia:phase ?phase ;
         oncologia:condition ?c ;
         oncologia:testsDrug ?drug .
  FILTER(?phase IN ("PHASE3", "PHASE2/PHASE3"))
  ?c oncologia:within ?breast .
  ?breast rdfs:label "Breast Neoplasms"@en .
  ?drug oncologia:name ?name ;
        oncologia:hasTarget ?target .
  ?target oncologia:gene "ERBB2" .
}
ORDER BY ?name

PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?trial) AS ?n) WHERE {
  ?trial a oncologia:Trial ;
         oncologia:phase ?phase ;
         oncologia:testsDrug ?drug .
  ?drug oncologia:hasTarget ?target .
  ?target oncologia:gene "EGFR" .
  FILTER(?phase IN ("PHASE3", "PHASE2/PHASE3"))
}

PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sponsorName WHERE {
  {
    SELECT ?sponsorName (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?t a oncologia:Trial ;
         oncologia:status ?st ;
         oncologia:sponsor ?s ;
         oncologia:condition ?c .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?c oncologia:within ?lung .
      ?lung rdfs:label "Lung Neoplasms"@en .
      ?s oncologia:industry true ;
         oncologia:name ?sponsorName .
    }
    GROUP BY ?sponsorName
    ORDER BY DESC(?n)
    LIMIT 3
  }
}
ORDER BY DESC(?n)

PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?reaction WHERE {
  ?r a oncologia:ReportedReaction ;
     oncologia:drug ?d ;
     oncologia:reaction ?reaction ;
     oncologia:reports ?n .
  ?d oncologia:name "IMATINIB" .
}
ORDER BY DESC(?n)
LIMIT 1

PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
