PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (SUM(?r) AS ?total) WHERE {
  ?y a oncologia:YearlyReports ;
     oncologia:drug ?d ;
     oncologia:year ?year ;
     oncologia:reports ?r .
  ?d oncologia:name "LENALIDOMIDE" .
  FILTER(?year < 2015)
}

PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ((100.0 * ?stopped / ?closed) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?t) AS ?closed)
    WHERE {
      ?t a oncologia:Trial ;
         oncologia:phase ?phase ;
         oncologia:status ?status ;
         oncologia:sponsor ?s .
      ?s oncologia:name ?sname .
      FILTER(LCASE(STR(?sname)) = "pfizer")
      FILTER(?phase IN ("PHASE2", "PHASE1/PHASE2", "PHASE2/PHASE3"))
      FILTER(?status IN ("COMPLETED", "TERMINATED", "WITHDRAWN"))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?t2) AS ?stopped)
    WHERE {
      ?t2 a oncologia:Trial ;
          oncologia:phase ?phase2 ;
          oncologia:status ?status2 ;
          oncologia:sponsor ?s2 .
      ?s2 oncologia:name ?sname2 .
      FILTER(LCASE(STR(?sname2)) = "pfizer")
      FILTER(?phase2 IN ("PHASE2", "PHASE1/PHASE2", "PHASE2/PHASE3"))
      FILTER(?status2 IN ("TERMINATED", "WITHDRAWN"))
    }
  }
}

