PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sponsorName WHERE {
  ?t a oncologia:Trial ;
     oncologia:phase ?phase ;
     oncologia:sponsor ?s ;
     oncologia:condition ?c .
  ?c oncologia:within ?crc .
