SELECT DISTINCT ?name WHERE {
  ?imatinib a oncologia:Drug ;
            oncologia:name "IMATINIB" ;
            oncologia:hasTarget ?target .
  ?drug a oncologia:Drug ;
        oncologia:hasTarget ?target ;
        oncologia:name ?name .
  FILTER(?drug != ?imatinib)
}
ORDER BY ?name
